export function ExceptionQueue({
  queueName = "{{queueName}}",
  reasonFilter = "{{reasonFilter}}",
  accent = "{{accent}}",
  showResolve = {{showResolve}},
}) {
  const rows = [
    { id: "Order #9021", reason: "fraud-check" },
    { id: "Order #9033", reason: "address-mismatch" },
    { id: "Order #9044", reason: "fraud-check" },
  ].filter((r) => reasonFilter === "all" || r.reason === reasonFilter);
  return (
    <div style={{ font: "12px/1.5 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 16, borderRadius: 12, width: 300, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 10px", fontWeight: 700 }}>{queueName}</p>
      {rows.map((r) => (
        <div key={r.id} style={{ display: "flex", alignItems: "center", gap: 8, padding: 8, borderRadius: 6, background: "#ffffff", border: "1px solid #24143014", marginBottom: 6 }}>
          {r.id}
          <span style={{ fontSize: 10, padding: "2px 7px", borderRadius: 999, color: "#241430", fontWeight: 600, background: accent }}>{r.reason}</span>
          {showResolve && <button type="button" style={{ marginLeft: "auto", border: "none", background: "#24143014", padding: "4px 9px", borderRadius: 6, fontSize: 10, fontWeight: 600, cursor: "pointer", color: "#241430" }}>Resolve</button>}
        </div>
      ))}
    </div>
  );
}
